import React, { Component } from "react";
import {
  Avatar, Button, LinearProgress, TextField, Grid, Box, Container, CircularProgress,
  Radio, FormControl, FormLabel, Snackbar, FormControlLabel, Autocomplete, FormGroup, MenuItem, Typography,
  Dialog, DialogTitle, DialogContent, DialogContentText, DialogActions,
} from '@mui/material';
import { IoLocationOutline } from "react-icons/io5"
import Alert from '@mui/material/Alert';
import ProcessRequest from '../ProcessAPI_Request';

import LoggedOut from "./CheckoutCompleted";

let Status = 0;

const EncodeURLInfo = (data) => {
  const bytes = new TextEncoder().encode(JSON.stringify(data));
  const binaryInfo = Array.from(bytes, (byte) => String.fromCharCode(byte)).join("");

  return encodeURIComponent(window.btoa(binaryInfo));
}

export default class CheckIn extends Component {
  constructor(props) {
    super(props);
    const queryParameters = new URLSearchParams(window.location.search)
    console.log(queryParameters)
    const userid = queryParameters.get("userid")
    const loginid = queryParameters.get("checkin_id")
    const env = queryParameters.get("env")
    // When launched from "My Visit Plan" with a selected visit, the client is
    // passed in and must be pre-filled and locked (non-editable).
    const lockedClientName = queryParameters.get("client")
    const lockedClientId = queryParameters.get("clientId")
    const LockedClient = queryParameters.get("locked") === "1" && !!lockedClientName
    // For a "Call" visit selected in My Visit Plan: auto-perform the check-in (no form)
    // and forward straight to checkout.
    const AutoCheckin = queryParameters.get("auto") === "1" && LockedClient
    const IsCall = queryParameters.get("visit") === "Call"
    // Interlink: planned slot id (email|week_start|slotId) carried from My Visit Plan → save.
    const plannedVisitId = queryParameters.get("planned_visit_id")
    this.state = {
      authentication: 0,
      env:env,
      userId: userid,
      PlannedVisitId: plannedVisitId,
      loginid: loginid,
      LockedClient: LockedClient,
      LockedClientId: lockedClientId,
      AutoCheckin: AutoCheckin,
      IsCall: IsCall,
      latitude: "NA",
      longitude: "NA",
      LocationEnabled: false,
      interval: null,
      SnackBar: false, SnackBarVariant: "warning", snackBarMessage: "", SnackbarTimeOut: 4000,
      Type: "",
      ClientVist: LockedClient ? 1 : -1,
      TravelType: null,
      TravelTypeData: [],
      ClientName: LockedClient ? lockedClientName : "",
      ClientsData: [],
      MasterData: {
        service: [], project: [], traveltype: [], product: [], rate: [], purposeofvisit: [], actionrequired: [], ClientsData: []
      },
      CheckinId: 0, UserType:"Sales", user_type_id: 0, isNewClient:false, ClientTypeData:[],
      CheckinLoader: false, LogoutFlag:false,
      Auto_Capture_Lat_Long:"",ClientType:"", vehicle_type:"two wheeler",
      division:"",
      ConfirmNewClientDialog: false, PendingClientName: "",
      NewClientDialog: false,
      NewClientName: "", NewClientPhone: "", NewClientContactPerson: "",
      NewClientCity: "", NewClientState: "", NewClientRegion: "",
      RegionsData: [], RegionsLoading: false, SavingNewClient: false,
    }
  }

  SnackbarActions = async (Data) => {
    if (Data.key === "Open") {
      await this.setState({ SnackBar: true, SnackBarVariant: Data.variant, snackBarMessage: Data.Message, SnackbarTimeOut: Data.TimeOut });
    } else {
      await this.setState({ SnackBar: false, SnackbarTimeOut: 10000 });
    }
  }
  async UsersCheckIn() {
    await this.setState({CheckinLoader:true});
    if(this.state.loginid === null){
      await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Alert: Login ID not generated to proceed....", TimeOut: 10000 });
    }else{
      if(this.state.Type===""){
        await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please Select Local/Outstation....!", TimeOut: 10000 });
      }else if(this.state.ClientVist === -1){
        await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please Client Visit....!", TimeOut: 10000 });
      }else if(this.state.TravelType === null){
        await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please Travel Type....!", TimeOut: 10000 });
      }else if(this.state.ClientName === "" || this.state.ClientName === null || this.state.ClientName === undefined){
        await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please Select Client Name....!", TimeOut: 10000 });
      }else if(this.state.ClientType==="" && this.state.isNewClient && this.state.ClientVist===1){
        await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please Select Client Type....!", TimeOut: 10000 });
      }else{
        navigator.geolocation.getCurrentPosition(async (coords, errorCallback) => {
          var RequestData = {
            urlapi: "salesvisit_stage/insertCheckinLog",
            method: "POST",
            data: {
              userid: this.state.userId,
              loginid: this.state.loginid, //LoginId which is received on "insertLoginLog" API
              username: this.state.userId,
              latitude: coords.coords.latitude,
              longitude: coords.coords.longitude
            }
          }
          console.log(RequestData);
          let response = await ProcessRequest(RequestData);
          console.log(response);
          if (response !== null) {
            if (response.respCode === 1 && response.respText === "success") {
              await this.SnackbarActions({ key: "Open", variant: "success", Message: "Success", TimeOut: 10000 });
              let ClientInfo = this.state.MasterData.ClientsData.find((data) => data.client_name === this.state.ClientName)
              // console.log(ClientInfo)
              if (ClientInfo === undefined) {
                ClientInfo = {
                  category: "",
                  client_name: this.state.ClientName,
                  id: "",
                  isNew: this.state.isNewClient,
                  ClientType: this.state.ClientType
                }
              } else {
                ClientInfo.isNew = false
              }
              let data = {
                userId: this.state.userId,
                ClientType: this.state.ClientType,
                TravelType: this.state.TravelType,
                VisitType: this.state.Type,
                SelectClient: ClientInfo,
                loginid: this.state.loginid,
                CheckinId: response.checkinid,
                UserType: response.type, //this.state.UserType,
                user_type_id: response.user_type_id, //this.state.user_type_id
                // vehicle_type: this.state.vehicle_type
                ClientVist: this.state.ClientVist, // 1-Yes, 0-No
                division: this.state.division,
                IsCall: this.state.IsCall, // true when a "Call" visit from My Visit Plan
                PlannedVisitId: this.state.PlannedVisitId // interlink to the planned slot
              }
              // console.log(data)
              // console.log(JSON.stringify(data));
              // console.log(URL_Data)
              // console.log(window.btoa(URL_Data))
              let URL_Data = EncodeURLInfo(data);
              if(this.state.env === "testing"){
                window.location.href = "/salesvisit_stage/checkout1?info=" + URL_Data;
              }else{
                window.location.href = "/salesvisit_stage/checkout?info=" + URL_Data;
              }
            } else if (response.respCode !== 1) {
              if (response.respCode === 5) {
                await this.SnackbarActions({ key: "Open", variant: "error", Message: response.respText, TimeOut: 10000 });
              } else {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: response.respText, TimeOut: 10000 });
              }
            }
          } else {
            await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Server Not Responding....!", TimeOut: 10000 });
          }
        });
      }
    }
    await this.setState({CheckinLoader:false});
  }
  componentDidMount = async () => {
    if (Status === 0 && !this.state.LogoutFlag) {
      Status = 1;
      await this.setState({ LoaderProgress: true })
      var Data = {
        urlapi: "salesvisit_stage/getSalesMasterData",
        method: "POST",
        data: { userId: this.state.userId }
      }
      console.log(Data);
      var resp = await ProcessRequest(Data);
      console.log(resp);
      await this.setState({SalesMasterData: JSON.stringify(resp), SalesMasterRequestData: JSON.stringify(Data)});
      if (resp !== null) {
        if (resp.respCode === 1 && resp.respText === "success") {
          resp.ClientsData = [];
          await this.setState({ 
            MasterData: resp,
            ClientTypeData: resp.clienttype,
            division:resp.branch,
            TravelType: 4,
            isNewClient:resp.branch==="EMI"?true:false,
            ClientType:resp.branch==="EMI"?"Oil & gas":""
          })
          if(resp.branch==="EMI"){
            await this.TypeChanges("Local");
            await this.ClientVisitChanges(1);
          }
          await this.SnackbarActions({ key: "Open", variant: "success", Message: "Data loaded successfully.....", TimeOut: 10000 });
        } else if (resp.respCode !== 1) {
          if (resp.respCode === 5) {
            await this.SnackbarActions({ key: "Open", variant: "error", Message: resp.respText, TimeOut: 10000 });
          } else {
            await this.SnackbarActions({ key: "Open", variant: "warning", Message: resp.respText, TimeOut: 10000 });
          }
        }
      } else {
        await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Server Not Responding....!", TimeOut: 10000 });
      }
      var Data1 = {
        urlapi: "salesvisit_stage/getClientDetails",
        method: "POST",
        data: { userid: this.state.userId }
      }
      console.log(Data1);
      var resp1 = await ProcessRequest(Data1);
      console.log(resp1);
      await this.setState({ClientsMasterData: JSON.stringify(resp1), ClientsMasterRequestData:JSON.stringify(Data1)});
      if (resp1 !== null) {
        if (resp1.respCode === 1 && resp1.respText === "success") {
          let data = this.state.MasterData;
          data.ClientsData = resp1.clientdetails;
          await this.setState({ MasterData: data, ClientsData: this.state.isNewClient?[]:resp1.clientdetails });
        } else if (resp1.respCode !== 1) {
          if (resp1.respCode === 5) {
            await this.SnackbarActions({ key: "Open", variant: "error", Message: resp1.respText, TimeOut: 10000 });
          } else {
            await this.SnackbarActions({ key: "Open", variant: "warning", Message: resp1.respText, TimeOut: 10000 });
          }
        }
      } else {
        await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Server Not Responding....!", TimeOut: 10000 });
      }
      await this.setState({ LoaderProgress: false })
      if (this.state.AutoCheckin) {
        // Call visit from My Visit Plan: client is already locked & Is-Client-Visit = Yes.
        // Default to Local + "At Actuals" (travel type id 1 — no km-distance flow), then
        // submit the check-in automatically and let it forward to checkout.
        await this.TypeChanges("Local");
        await this.setState({ Type: "Local", TravelType: 1, ClientVist: 1 });
        await this.UsersCheckIn();
      }
      Status = 0;
    }
  }
  TypeChanges = async (value) => {
    await this.setState({ Type: value, TravelTypeData: this.state.MasterData.traveltype.filter((data) => data.local_outstation === value) });
  }
  ClientVisitChanges = async (val) => {
    await this.setState({
      ClientVist: val,
      ClientsData: this.state.MasterData.ClientsData.filter((data) => data.visitflag === val),
      ClientName: this.state.LockedClient ? this.state.ClientName : "",
      isNewClient: false,
      ClientType: "",
    })
  }
  SelectedClientName = async (name) => {
    if (!name || name.trim() === "") return;
    let CheckClientName = this.state.ClientsData.find((data) => data.client_name === name);
    if (CheckClientName !== undefined) {
      await this.setState({ ClientName: name, isNewClient: false });
    } else {
      await this.setState({ PendingClientName: name, ConfirmNewClientDialog: true });
    }
  }
  ConfirmNewClient = async () => {
    await this.setState({
      ConfirmNewClientDialog: false,
      NewClientDialog: true,
      NewClientName: this.state.PendingClientName,
      NewClientPhone: "",
      NewClientContactPerson: "",
      NewClientCity: "",
      NewClientState: "",
      NewClientRegion: "",
      PendingClientName: "",
    });
    this.FetchRegions();
  }
  CancelNewClient = async () => {
    await this.setState({
      PendingClientName: "",
      ConfirmNewClientDialog: false,
      ClientName: "",
    });
  }
  FetchRegions = async () => {
    if (this.state.RegionsData.length > 0) return;
    await this.setState({ RegionsLoading: true });
    var Data = {
      urlapi: "salesvisit_stage/getRegions",
      method: "POST",
      data: { userid: this.state.userId }
    }
    let resp = await ProcessRequest(Data);
    if (resp !== null && resp.respCode === 1) {
      await this.setState({ RegionsData: Array.isArray(resp.regions) ? resp.regions : [] });
    } else {
      await this.SnackbarActions({ key: "Open", variant: "warning", Message: resp !== null ? resp.respText : "Unable to load regions....!", TimeOut: 6000 });
    }
    await this.setState({ RegionsLoading: false });
  }
  SaveNewClientDetails = async () => {
    const name    = this.state.NewClientName.trim();
    const phone   = this.state.NewClientPhone.trim();
    const contact = this.state.NewClientContactPerson.trim();
    const city    = this.state.NewClientCity.trim();
    const stateNm = this.state.NewClientState.trim();
    const region  = this.state.NewClientRegion;
    if (name === "") {
      await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please enter Client Name....!", TimeOut: 6000 }); return;
    }
    if (!/^\d{10}$/.test(phone)) {
      await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please enter a valid 10-digit Phone Number....!", TimeOut: 6000 }); return;
    }
    if (contact === "") {
      await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please enter Contact Person Name....!", TimeOut: 6000 }); return;
    }
    if (city === "") {
      await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please enter City....!", TimeOut: 6000 }); return;
    }
    if (stateNm === "") {
      await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please enter State....!", TimeOut: 6000 }); return;
    }
    if (!region) {
      await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select Region....!", TimeOut: 6000 }); return;
    }
    await this.setState({ SavingNewClient: true });
    var Data = {
      urlapi: "salesvisit_stage/saveTempClientDetails",
      method: "POST",
      data: {
        client_name:    name,
        phone_number:   phone,
        contact_person: contact,
        city:           city,
        state:          stateNm,
        region:         region,
        visitflag:      this.state.ClientVist,
        loginid:        this.state.loginid,
        userid:         this.state.userId
      }
    }
    let resp = await ProcessRequest(Data);
    if (resp !== null && resp.respCode === 1 && resp.respText === "success") {
      // Add to the visible dropdown list for this session (kept out of MasterData.ClientsData
      // so the check-in still treats it as a new/user-added client).
      const newClientEntry = { id: "", client_name: name, category: "", visitflag: this.state.ClientVist };
      const alreadyListed = this.state.ClientsData.some((d) => d.client_name === name);
      await this.setState({
        ClientName: name,
        isNewClient: true,
        NewClientDialog: false,
        SavingNewClient: false,
        ClientsData: alreadyListed ? this.state.ClientsData : [...this.state.ClientsData, newClientEntry],
      });
      await this.SnackbarActions({ key: "Open", variant: "success", Message: "New client saved. You can now check in.", TimeOut: 6000 });
    } else {
      await this.setState({ SavingNewClient: false });
      await this.SnackbarActions({ key: "Open", variant: "warning", Message: resp !== null ? resp.respText : "Server Not Responding....!", TimeOut: 6000 });
    }
  }
  CancelNewClientDetails = async () => {
    await this.setState({
      NewClientDialog: false,
      NewClientName: "", NewClientPhone: "", NewClientContactPerson: "",
      NewClientCity: "", NewClientState: "", NewClientRegion: "",
      SavingNewClient: false,
      ClientName: "",
    });
  }
  render() {
    return (
      <div>
        <Container component="main" maxWidth="xs">
          <pre>

          </pre>
          {this.state.LogoutFlag?
            <LoggedOut/>
          : this.state.AutoCheckin?
            <Box style={{ marginTop: 140, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 18 }}>
              <CircularProgress color="primary" />
              <Typography variant="h6" style={{ color: '#1a237e' }}>Checking you in…</Typography>
              <Typography variant="body2" style={{ color: '#666' }}>{this.state.ClientName}</Typography>
            </Box>
          :
            <Box style={{ marginTop: 100, borderTopLeftRadius: 20, borderTopRightRadius: 20, borderBottomLeftRadius: 20, borderBottomRightRadius: 20, display: 'flex', flexDirection: 'column', backgroundColor: "white", padding: 20, alignItems: 'center' }} boxShadow={3}>
              <Grid container style={{ marginTop: -20, marginBottom: 26 }}>
                <Grid item xs={12}>
                  {this.state.LoaderProgress ? <LinearProgress color="primary" /> : <></>}
                </Grid>
              </Grid>
              <Avatar style={{ marginBottom: 40, background: 'linear-gradient(45deg,#1a237e 30%, #0d47a1 90%)', boxShadow: '0 3px 5px 2px #84817a' }}>
                <IoLocationOutline />
              </Avatar>
              <Grid container spacing={2}>
                <Grid item xs={12}>
                  <FormControl component="fieldset" variant="standard" id="type">
                    <FormLabel component="legend">Type</FormLabel>
                    <FormGroup row>
                      <FormControlLabel
                        value="Local"
                        control={
                          <Radio
                            checked={this.state.Type === "Local"}
                            onChange={() => this.TypeChanges("Local")}
                            disabled={this.state.LoaderProgress||this.state.division==="EMI"}
                          />
                        }
                        label="Local"
                      />
                      <FormControlLabel
                        value="Outstation"
                        control={
                          <Radio
                            checked={this.state.Type === "Outstation"}
                            onChange={() => this.TypeChanges("Outstation")}
                            disabled={this.state.LoaderProgress||this.state.division==="EMI"}
                          />
                        }
                        label="Outstation"
                      />
                    </FormGroup>
                  </FormControl>
                </Grid>
                {/* {this.state.TravelType===4?
                  <Grid item xs={12}>
                    <FormControl component="fieldset" variant="standard" id="vehicle_type">
                      <FormLabel component="legend">Vehicle Type</FormLabel>
                      <FormGroup row>
                        <FormControlLabel control={<Radio checked={this.state.vehicle_type==="two wheeler"} onClick={(e)=>this.setState({vehicle_type:"two wheeler"})} />} label="Two Wheeler" />
                        <FormControlLabel control={<Radio checked={this.state.vehicle_type==="four wheeler"} onClick={(e)=>this.setState({vehicle_type:"four wheeler"})} />} label="Four Wheeler" />
                      </FormGroup>
                    </FormControl>
                  </Grid>
                :
                  <></>
                } */}
                <Grid item xs={12}>
                  <TextField select label="Travel Type" InputLabelProps={{shrink:true}} value={this.state.TravelType} fullWidth onChange={(event) => this.setState({ TravelType: event.target.value })} disabled={this.state.LoaderProgress||this.state.division==="EMI"}>
                    {this.state.TravelTypeData.map((data)=>{
                      return(
                        <MenuItem value={data.id}>{data.travel_type}</MenuItem>
                      )
                    })}
                  </TextField>
                </Grid>
                <Grid item xs={12}>
                  <FormControl component="fieldset" variant="standard" id='ClientVisitStatus'>
                    <FormLabel component="legend">Is Client Visit</FormLabel>
                    <FormGroup row>
                      <FormControlLabel
                        value="Yes"
                        control={
                          <Radio
                            checked={this.state.ClientVist === 1}
                            onChange={() => this.ClientVisitChanges(1)}
                            disabled={this.state.LoaderProgress||this.state.division==="EMI"||this.state.LockedClient}
                          />
                        }
                        label="Yes"
                      />
                      <FormControlLabel
                        value="No"
                        control={
                          <Radio
                            checked={this.state.ClientVist === 0}
                            onChange={() => this.ClientVisitChanges(0)}
                            disabled={this.state.LoaderProgress||this.state.division==="EMI"||this.state.LockedClient}
                          />
                        }
                        label="No"
                      />
                    </FormGroup>
                  </FormControl>
                </Grid>
                <Grid item xs={12}>
                  {this.state.LockedClient ?
                    <TextField
                      label="Client Name"
                      fullWidth
                      value={this.state.ClientName}
                      disabled
                      InputLabelProps={{ shrink: true }}
                      helperText="Selected from your visit plan"
                    />
                  :
                    <Autocomplete
                      disabled={this.state.LoaderProgress}
                      freeSolo
                      key={this.state.ClientVist}
                      id="AutoComplete_ClientsData"
                      options={this.state.ClientsData.map((data) => data.client_name)}
                      fullWidth
                      onBlur={(event) => {
                        const typedValue = event.target.value;
                        if (typedValue && typedValue !== this.state.ClientName) {
                          this.SelectedClientName(typedValue);
                        }
                      }}
                      onChange={(event, newValue) => {
                        if (newValue) {
                          this.setState({ ClientName: newValue, isNewClient: false });
                        } else {
                          this.setState({ ClientName: "", isNewClient: false });
                        }
                      }}
                      renderInput={(params) => <TextField {...params} label="Client Name" />}
                    />
                  }
                </Grid>
                <Grid item xs={12}>
                  {this.state.isNewClient && this.state.ClientVist===1?
                    <TextField select disabled={this.state.LoaderProgress||this.state.division==="EMI"} label="Client Type" value={this.state.ClientType} fullWidth onChange={(event) => this.setState({ ClientType: event.target.value })}>
                      {this.state.ClientTypeData.map((data)=>{
                        return(
                          <MenuItem value={data.ClientType}>{data.ClientType}</MenuItem>
                        )
                      })}
                    </TextField>
                  :
                    <></>
                  }
                </Grid>
                <Grid item xs={12}>
                  {this.state.CheckinLoader?
                    <Button 
                      disabled={this.state.LoaderProgress}
                      style={{
                        background: 'linear-gradient(45deg,#1a237e 30%, #0d47a1 90%)',
                        border: 0,
                        borderRadius: 3,
                        boxShadow: '0 3px 5px 2px #84817a',
                        color: 'white',
                        height: 48,
                        width: '100%',
                        outline: 'none',
                        padding: '0 30px'
                      }}
                      variant="outlined"
                    >
                      Check In &nbsp;&nbsp; <CircularProgress style={{height:16,width:16}} color="inherit" />
                    </Button>
                  :
                    <Button 
                      disabled={this.state.LoaderProgress}
                      style={{
                        background: 'linear-gradient(45deg,#1a237e 30%, #0d47a1 90%)',
                        border: 0,
                        borderRadius: 3,
                        boxShadow: '0 3px 5px 2px #84817a',
                        color: 'white',
                        height: 48,
                        width: '100%',
                        outline: 'none',
                        padding: '0 30px'
                      }}
                      variant="outlined"
                      onClick={()=>this.UsersCheckIn()}
                    >
                      Check In
                    </Button>
                  }
                </Grid>
              </Grid>
              <Typography style={{paddingTop:20}}>ID: {this.state.loginid}</Typography>
            </Box>
          }
          <Dialog
            open={this.state.ConfirmNewClientDialog}
            onClose={this.CancelNewClient}
            maxWidth="xs"
            fullWidth
            PaperProps={{ sx: { mx: { xs: 2, sm: 3 }, borderRadius: 2 } }}
          >
            <DialogTitle sx={{ fontWeight: 'bold', pb: 1 }}>New Client</DialogTitle>
            <DialogContent>
              <DialogContentText>
                <strong>"{this.state.PendingClientName}"</strong> is not found in the client list. Do you want to check in as a new client?
              </DialogContentText>
            </DialogContent>
            <DialogActions sx={{ p: 2, gap: 1 }}>
              <Button onClick={this.CancelNewClient} variant="outlined" fullWidth>Cancel</Button>
              <Button onClick={this.ConfirmNewClient} variant="contained" color="primary" fullWidth autoFocus>Confirm</Button>
            </DialogActions>
          </Dialog>
          <Dialog
            open={this.state.NewClientDialog}
            onClose={this.CancelNewClientDetails}
            maxWidth="xs"
            fullWidth
            PaperProps={{ sx: { mx: { xs: 2, sm: 3 }, borderRadius: 2 } }}
          >
            <DialogTitle sx={{ fontWeight: 'bold', pb: 1 }}>Add New Client</DialogTitle>
            <DialogContent>
              <Grid container spacing={2} sx={{ mt: 0 }}>
                <Grid item xs={12}>
                  <TextField
                    label="Client Name"
                    fullWidth
                    value={this.state.NewClientName}
                    onChange={(e) => this.setState({ NewClientName: e.target.value })}
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    label="Phone Number"
                    fullWidth
                    value={this.state.NewClientPhone}
                    inputProps={{ inputMode: 'numeric', maxLength: 10 }}
                    onChange={(e) => this.setState({ NewClientPhone: e.target.value.replace(/\D/g, '').slice(0, 10) })}
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    label="Contact Person Name"
                    fullWidth
                    value={this.state.NewClientContactPerson}
                    onChange={(e) => this.setState({ NewClientContactPerson: e.target.value })}
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    label="City"
                    fullWidth
                    value={this.state.NewClientCity}
                    onChange={(e) => this.setState({ NewClientCity: e.target.value })}
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    label="State"
                    fullWidth
                    value={this.state.NewClientState}
                    onChange={(e) => this.setState({ NewClientState: e.target.value })}
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    select
                    label="Region"
                    fullWidth
                    value={this.state.NewClientRegion}
                    disabled={this.state.RegionsLoading}
                    helperText={this.state.RegionsLoading ? "Loading regions..." : ""}
                    onChange={(e) => this.setState({ NewClientRegion: e.target.value })}
                  >
                    {this.state.RegionsData.map((region, idx) => (
                      <MenuItem key={idx} value={region}>{region}</MenuItem>
                    ))}
                  </TextField>
                </Grid>
              </Grid>
            </DialogContent>
            <DialogActions sx={{ p: 2, gap: 1 }}>
              <Button onClick={this.CancelNewClientDetails} variant="outlined" fullWidth disabled={this.state.SavingNewClient}>Cancel</Button>
              <Button onClick={this.SaveNewClientDetails} variant="contained" color="primary" fullWidth disabled={this.state.SavingNewClient}>
                {this.state.SavingNewClient ? <>Saving &nbsp;<CircularProgress style={{ height: 16, width: 16 }} color="inherit" /></> : "Save"}
              </Button>
            </DialogActions>
          </Dialog>
          <Snackbar
            open={this.state.SnackBar}
            autoHideDuration={this.state.SnackbarTimeOut}
            onClose={() => this.SnackbarActions({ key: "Close", variant: "warning" })}
            anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
          >
            <Alert onClose={() => this.SnackbarActions({ key: "Close" })} severity={this.state.SnackBarVariant} sx={{ width: '100%' }}>
              {this.state.snackBarMessage}
            </Alert>
          </Snackbar>
        </Container >
      </div>
    );
  }
}


